}
if(b.broadcast_id){
  const rowr0=await sget('broadcasts?id=eq.'+encodeURIComponent(String(b.broadcast_id))+'&tenant_id=eq.'+TID+'&select=body');
  const cfg0=parse((Array.isArray(rowr0)&&rowr0[0]&&rowr0[0].body)||'{}')||{};
  prevProgress=cfg0.progress||{};
  if(RESUME){
    const lease=prevProgress.lease_until?new Date(prevProgress.lease_until).getTime():0;
    if(lease>Date.now()) return [{json:{ok:false,busy:true,error:'This campaign is being continued by another run right now; try again in a minute.'}}];
    prevRecipients=Array.isArray(cfg0.recipients)?cfg0.recipients:[];
  }
  /* lease: while this run sends, no other run continues the same campaign */
  cfg0.progress=Object.assign({},prevProgress,{total:members.length,done:prevRecipients.length,lease_until:new Date(Date.now()+330000).toISOString()});
  try{ await H.httpRequest({method:'PATCH',url:SUPA+'/rest/v1/broadcasts?id=eq.'+encodeURIComponent(String(b.broadcast_id))+'&tenant_id=eq.'+TID,headers:{...sH,'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify({body:JSON.stringify(cfg0)})}); }catch(e){}
}
const doneKeys=new Set(prevRecipients.map(rkey));
const lastSentAt={};
for(let i=0;i<ordered.length;i++){
  const m=ordered[i];
  if(doneKeys.has(rkey(m))) continue;
  if(b.broadcast_id&&(sentThisRun>=BATCH||Date.now()-RUN_T0>BUDGET_MS)){ partial=true; break; }
  sentThisRun++;
  const nk=pkey(m.phone);
  if(nk&&lastSentAt[nk]){ const wait=6500-(Date.now()-lastSentAt[nk]); if(wait>0) await sleep(wait); }
  let r;
  try{ r=await sendOne(m.phone,b.template,b.language,b.vars,m,imgUrl); }
  catch(e){ r={ok:false,wamid:null,to:sendNum(m.phone),err:'not sent: '+String((e&&e.message)||e).slice(0,200)}; }
  if(nk) lastSentAt[nk]=Date.now();
  if(r.ok) {
    sent++;
    recipientsTracker.push({
      id: m.id || null,
      row_no: m.row_no || null,
      name: m.full_name || 'Member',
      phone: r.to||sendNum(m.phone),
      wamid: r.wamid,
      status: 'sent',
      sent_at: new Date().toISOString()
    });
  } else {
    failed++;
    if(errs.length<5) errs.push(r.err);
    recipientsTracker.push({
      id: m.id || null,
      row_no: m.row_no || null,
      name: m.full_name || 'Member',
      phone: r.to||sendNum(m.phone),
      wamid: null,
      status: 'failed',
      error: r.err,
      sent_at: new Date().toISOString()
    });
  }
  if((i+1)%10===0) await new Promise(res=>setTimeout(res,300)); // ~33 msg/s ceiling
}
// ---- record stats back on the campaign row ----
if(b.broadcast_id){ try{
  const rowr=await H.httpRequest({method:'GET',url:SUPA+'/rest/v1/broadcasts?id=eq.'+encodeURIComponent(String(b.broadcast_id))+'&tenant_id=eq.'+TID+'&select=body',headers:sH,json:true});
  let cfg={}; try{ cfg=JSON.parse(((rowr&&rowr[0]&&rowr[0].body)||'{}')); }catch(e){}
  /* in sheet order (rows that share a number were sent in rounds); earlier batches first */
  const all=prevRecipients.concat(recipientsTracker).sort((x,y)=>(x.row_no||0)-(y.row_no||0));
  /* a recipient of an earlier batch may already be delivered/read (Meta's reports update the row meanwhile): every successful send counts */
  sent=all.filter(x=>x.wamid&&x.status!=='failed').length; failed=all.filter(x=>x.status==='failed').length;
  cfg.recipients=all;
  cfg.stats={ sent, failed, delivered:(cfg.stats&&cfg.stats.delivered)||0, read:(cfg.stats&&cfg.stats.read)||0, at:new Date().toISOString() };
  if(partial){
    cfg.progress={ total:members.length, done:all.length, next_at:new Date().toISOString(), lease_until:null, batches:Number(prevProgress.batches||0)+1 };
    cfg.stats.partial=true;
    await H.httpRequest({method:'PATCH',url:SUPA+'/rest/v1/broadcasts?id=eq.'+encodeURIComponent(String(b.broadcast_id))+'&tenant_id=eq.'+TID,
      headers:{...sH,'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify({sent_count:sent,body:JSON.stringify(cfg)})});
  } else {
    delete cfg.progress;
    const fin={status:'sent',sent_count:sent,body:JSON.stringify(cfg)}; if(!RESUME) fin.sent_at=STARTED_AT;
    await H.httpRequest({method:'PATCH',url:SUPA+'/rest/v1/broadcasts?id=eq.'+encodeURIComponent(String(b.broadcast_id))+'&tenant_id=eq.'+TID,
      headers:{...sH,'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify(fin)});
  }
}catch(e){} }
const doneCount=prevRecipients.length+recipientsTracker.length;
return [{json:{ok:true,dry_run:false,sent_by:who,tenant:t.name,audience_count:members.length,skipped_opted_out:optedOut||undefined,sent,failed,errors:errs,
  partial:partial||undefined,done:partial?doneCount:undefined,remaining:partial?(members.length-doneCount):undefined,broadcast_id:b.broadcast_id||undefined}}];
}catch(e){ return [{json:{ok:false,error:String((e&&e.message)||e)}}]; }
